draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw gut
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.bezierCurveTo(W/2 - 50, H/2 - 50, W/2 + 50, H/2 - 50, W/2 + 100, H/2);
  ctx.stroke();

  // Draw probiotics
  ctx.fillStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 - 50 + i * 20, H/2 - 20 + 10 * Math.sin(t + i), 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  // Draw fermentation bubbles
  ctx.fillStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 50 + i * 20, H/2 + 20 + 10 * Math.cos(t + i), 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
